architecture.h4_f:
msg = CBOR{v:1, besedilo, reply_to, sent_at}
ct = AES-GCM-256-Šifriraj(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, besedilo, reply_to?, thread_id?, mentions?, sent_at}
ct = AES-GCM-256-Šifriraj(ključ_sobe, nonce, pt, aad=hex(id_sobe))
žica = CBOR{
  v: 1,
  šifrirano besedilo: hex(ct), // spremenljiva dolžina
  enkrat: hex (12 B),
  psevdo pošiljatelja: hex (16 B),
  sent_at: unix_ms
}

cryptoWire.h5_f:
zunanji = CBOR{
  izvorno_vozlišče: hex32,
  ciljni_uporabnik: int64,
  notranja šifra: bajti,
  notranji_nonce: bajti,
  sent_at: unix_ms
}
sig = Ed25519-Sign(source_priv, zunanji)
POST /federation/deliver { ovojnica: zunanja, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { uporabniško ime, geslo, x25519_javni_ključ, prikazno_ime, telefon?, e-pošta?, avatar_emoji }

Odgovor 201 ustvarjen:
  { access_token, refresh_token, user_id, uporabniško ime, ... }

auth.h3_f:
tovor access_token:
  { sub: user_id, jti: device_id, typ: "access", exp: zdaj + 15 min }
koristni token refresh_token:
  { sub: user_id, jti: device_id, typ: "osveži", exp: zdaj + 30d }

HS256 podpisano s 64-bajtno skrivnostjo vozlišča iz .env

auth.h4_f:
register_begin(): izziv = rand(32)
                    možnosti = { rp.id, user.id, pubKeyCredParams, izziv}
                    možnosti vračila

register_finish(potrdilo):
  preveri potrdilo glede na TPM / Secure Enclave root CA
  shranjujte {credential_id, public_key, counter: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → {nonce: 128-bit hex, ttl: 60}
QR payload = {nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → registrirana nova naprava; JWT-ji so se vrnili.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
šifrirano besedilo = AES-GCM-Šifriraj(ključ_sobe, nonce, CBOR_payload, aad=id_sobe)

Razširjeni okvir: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {ime datoteke, velikost, chunk_size_hint}
            ← {upload_id, chunk_size}
kos PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bajtov>
            ← 204
dokončaj POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL na nedokončano: 24 h

files.h4_f:
seznam_zavrnitev = {
  "aplikacija/x-dosexec",
  "aplikacija/x-sharedlib",
  "aplikacija/x-mach-binary",
}
if magic.from_buffer(buf[:1024]) in deny_list: vrni 415

presence.h1_f:
odjemalec: ob prvem pritisku tipke → pošlji {type:"t", state:"start"}
         ne pošilja več 3 s, razen če se stanje spremeni
         10 s po zadnjem pritisku tipke → pošlji {type:"t", state:"stop"}
sprejemnik: samodejna zaustavitev 10 s po zadnjem "zagonu", če ni prispel "stop".

presence.h2_f:
POST /api/rooms/{id}/read { last_read_message_id }

if user.hides_receipts:
   ne vztrajati; ne oddajajte
   temu uporabniku ne pošiljajte računov drugih
drugače:
   UPSERT potrdila o branju VALUES (room_id, user_id, message_id, NOW())
   oddaja {type:"r", room, user, message_id}

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS oddaja {type:"c", kind:"invite", call_id}
WS oddaja {type:"c", kind:"offer", sdp}
WS oddaja {type:"c", kind:"answer", sdp}
WS oddaja {type:"c", kind:"candidate",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
ovojnica = {
  izvorno_vozlišče: hex32,
  ciljni_uporabnik: int64,
  notranja šifra: bajti,
  notranji_nonce: bajti,
  sent_at: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(ovojnica))
POST /federation/deliver { kuverta, sig }

gossip.h3_f:
oglas = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(oglas))
vsebina tračev: [..., {ad, sig}, ...]

sprejemnik: preveri sig glede na ad.pubkey → shrani, če je ok
dodatno: PoW 2^18 začetnih ničel na {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template with {
  random = naš random,
  server_name = naše ime gostitelja (ali zavito v ECH),
  session_id = naš ID seje,
}
JA4 = t13d_xxxx_xxxx_xxxx (ujema se s trenutno stabilno različico Chroma)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {name: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(javni_ključ_iz_HTTPS_zapisa)
DGA: domena(t) = base32( SHA256(seme ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) {decrypt(remoteMessage.data)}
Splet SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
orodje = sign_tool
input = izvorno drevo, ključi/release.key
manifest = {
  različica: "0.1.0",
  vgrajeno: unix_ms,
  datoteke: [{pot, sha256, velikost}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
izhod = INTEGRITY.sig.json = {manifest, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
ustvari: POST /api/bots {uporabniško ime, prikazno_ime, koda}
          → {bot_id, žeton, pubkey}
zagon: v procesu (soprogram znotraj vozlišča)
      OR zunanji (long-poll /api/bots/{id}/updates, token-auth'd)
sporočilo: {besedilo, podpis: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
na /start {
  odda "Dobrodošli, {ctx.first_name}"
}
on /add <item> {
  state.list = (state.list ali []) + [ctx.args.item]
  emit "Dodano: {ctx.args.item}"
}

security.h4_f:
canary.txt (vsak dan):
  {datum, sig: Ed25519-Sign(release_priv, date)}
odjemalec preveri → odsoten ali neveljaven ⇒ sum ogroženosti

nujno:
  admin POST /api/admin/revoke-all {razlog}
  vozlišče oddaja {type:"n", event:"compromise", reason}
  odjemalci izbrišejo ključe, prisilijo ponovni zagon

debugging.h2_f:
histogrami stopnje (na pot + metodo):
  vortex_http_requests_total{route,method,status}
  vortex_http_request_duration_seconds_bucket{route,method,le}

merilniki spletne vtičnice:
  vortex_ws_connections{vozlišče}
  vortex_ws_fanout_queue_depth{soba,uporabnik}

števci po meri:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{vrsta}

